# Adds questions for the Social Science skills that had none (v44). All start as needs_review (pilot subject).
import json, os
P = os.path.join(os.path.dirname(__file__), '..', 'seed', 'cbse-class10-social-science-diagnostic.json')
def Q(skill, diff, prompt, ans, wrong, expl, tag='CONCEPT_CONFUSION'):
    return {'skill_slug': skill, 'difficulty': diff, 'question_type': 'mcq', 'prompt': prompt,
            'expected_answer': {'value': ans}, 'misconception_tags': [tag], 'options': [ans] + wrong, 'explanation': expl}
